import React, { useState } from 'react';
import {
  Sparkles,
  X,
  Send,
  Loader2,
  CheckCircle2,
  AlertCircle,
  HelpCircle,
  CalendarDays,
  ArrowRight,
} from 'lucide-react';
import { apiFetch } from '../utils/api.js';

export default function AiTaskModal({
  isOpen,
  onClose,
  onTaskCreated,
  isDarkMode = false,
}) {
  const [prompt, setPrompt] = useState('');
  const [isInterpreting, setIsInterpreting] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');
  const [clarificationMsg, setClarificationMsg] = useState('');
  const [interpretationResult, setInterpretationResult] = useState(null);

  if (!isOpen) return null;

  const handleReset = () => {
    setPrompt('');
    setErrorMsg('');
    setClarificationMsg('');
    setInterpretationResult(null);
  };

  const handleClose = () => {
    handleReset();
    onClose();
  };

  const handleInterpret = async (e) => {
    if (e) e.preventDefault();
    if (!prompt.trim() || isInterpreting) return;

    setIsInterpreting(true);
    setErrorMsg('');
    setClarificationMsg('');
    setInterpretationResult(null);

    try {
      const res = await apiFetch('/api/ai/interpret-task', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: prompt.trim() }),
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok || data.status === 'error') {
        throw new Error(data.message || 'Erro ao processar interpretação com a IA.');
      }

      if (data.status === 'needs_info') {
        setClarificationMsg(data.message || 'Precisamos de mais algumas informações.');
      } else if (data.status === 'ready_for_confirmation') {
        setInterpretationResult(data);
      }
    } catch (err) {
      console.error('Erro ao interpretar tarefa:', err);
      setErrorMsg(err.message || 'Não foi possível conectar ao serviço de IA.');
    } finally {
      setIsInterpreting(false);
    }
  };

  const handleConfirmAndSave = async () => {
    if (!interpretationResult?.structuredTask || isSaving) return;

    setIsSaving(true);
    setErrorMsg('');

    try {
      const payload = interpretationResult.structuredTask;

      const res = await apiFetch('/api/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.message || 'Erro ao salvar a tarefa no banco de dados.');
      }

      const responseData = await res.json().catch(() => ({}));
      const createdTask = responseData.task || payload;

      // Dispara evento global de atualização para todos os modelos recarregarem
      window.dispatchEvent(
        new CustomEvent('focusmod_task_created', {
          detail: { task: createdTask },
        })
      );

      if (onTaskCreated) {
        onTaskCreated(createdTask);
      }

      handleClose();
    } catch (err) {
      console.error('Erro ao salvar tarefa confirmada:', err);
      setErrorMsg(err.message || 'Erro ao salvar a tarefa.');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-slate-900/60 backdrop-blur-xs transition-opacity animate-in fade-in duration-200"
        onClick={handleClose}
        aria-hidden="true"
      />

      {/* Modal Card */}
      <div
        className={`relative z-50 w-full max-w-lg rounded-2xl border shadow-2xl overflow-hidden flex flex-col animate-in zoom-in-95 duration-200 transition-colors ${
          isDarkMode
            ? 'bg-slate-900 border-slate-800 text-slate-100'
            : 'bg-white border-[#d3dce6] text-slate-900'
        }`}
      >
        {/* Header */}
        <div
          className={`px-5 py-3.5 border-b flex items-center justify-between shrink-0 ${
            isDarkMode ? 'bg-slate-950 border-slate-800' : 'bg-[#f4f7fa] border-[#d3dce6]'
          }`}
        >
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-gradient-to-tr from-indigo-600 via-blue-600 to-cyan-500 text-white flex items-center justify-center shadow-xs">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <h2 className="text-sm sm:text-base font-bold leading-tight flex items-center gap-2">
                <span>Criar Tarefa com IA</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded-full font-mono font-normal bg-indigo-500/10 text-indigo-500 border border-indigo-500/20">
                  DeepSeek
                </span>
              </h2>
              <p className="text-[11px] text-slate-400">
                Descreva sua tarefa em linguagem natural
              </p>
            </div>
          </div>

          <button
            type="button"
            onClick={handleClose}
            className={`p-1.5 rounded-lg transition-colors cursor-pointer ${
              isDarkMode
                ? 'text-slate-400 hover:text-white hover:bg-slate-800'
                : 'text-slate-400 hover:text-slate-700 hover:bg-[#e8edf2]'
            }`}
            title="Fechar"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Content Body */}
        <div className="p-5 space-y-4 max-h-[75vh] overflow-y-auto">
          {/* Mensagem de Erro */}
          {errorMsg && (
            <div className="p-3 rounded-xl bg-rose-50 border border-rose-200 text-rose-800 text-xs flex items-start gap-2.5">
              <AlertCircle className="w-4 h-4 shrink-0 text-rose-600 mt-0.5" />
              <span>{errorMsg}</span>
            </div>
          )}

          {/* Feedback de Esclarecimento / Necessita de mais informações */}
          {clarificationMsg && !interpretationResult && (
            <div
              className={`p-3.5 rounded-xl border text-xs flex items-start gap-2.5 ${
                isDarkMode
                  ? 'bg-amber-950/40 border-amber-800/60 text-amber-300'
                  : 'bg-amber-50 border-amber-200 text-amber-900'
              }`}
            >
              <HelpCircle className="w-4 h-4 shrink-0 text-amber-500 mt-0.5" />
              <div className="space-y-1">
                <p className="font-bold text-[11px] uppercase tracking-wider text-amber-600 dark:text-amber-400">
                  Informação Adicional Necessária
                </p>
                <p className="leading-relaxed">{clarificationMsg}</p>
              </div>
            </div>
          )}

          {/* Estado de Interpretação Concluída: Exibe Modal/Card de Confirmação */}
          {interpretationResult ? (
            <div className="space-y-4 animate-in fade-in duration-200">
              <div
                className={`p-4 rounded-xl border ${
                  isDarkMode
                    ? 'bg-slate-950/70 border-slate-800'
                    : 'bg-[#f8fafc] border-[#e2e8f0]'
                }`}
              >
                <div className="flex items-center gap-2 mb-3 pb-2 border-b border-slate-200 dark:border-slate-800">
                  <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                  <h3 className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                    Entendi que você quer criar:
                  </h3>
                </div>

                <ul className="space-y-2 text-xs">
                  {interpretationResult.summaryFields?.map((item, idx) => (
                    <li key={idx} className="flex items-start justify-between gap-3">
                      <span className="font-medium text-slate-400 text-[11px]">
                        {item.label}:
                      </span>
                      <span className="font-bold text-right text-slate-800 dark:text-slate-200 break-words">
                        {item.value}
                      </span>
                    </li>
                  ))}
                </ul>

                <p className="mt-3.5 pt-2.5 border-t border-slate-200 dark:border-slate-800 text-[11px] text-slate-500 text-center font-medium">
                  Está correto? Confirme abaixo para salvar definitivamente no banco de dados.
                </p>
              </div>

              {/* Ações de Confirmação */}
              <div className="flex items-center justify-end gap-2.5 pt-1">
                <button
                  type="button"
                  onClick={() => setInterpretationResult(null)}
                  disabled={isSaving}
                  className={`px-3.5 py-2 rounded-xl text-xs font-semibold border transition-colors cursor-pointer ${
                    isDarkMode
                      ? 'border-slate-700 text-slate-300 hover:bg-slate-800'
                      : 'border-[#d3dce6] text-slate-600 hover:bg-slate-100'
                  }`}
                >
                  Corrigir mensagem
                </button>

                <button
                  type="button"
                  onClick={handleConfirmAndSave}
                  disabled={isSaving}
                  className="px-4 py-2 rounded-xl text-xs font-bold text-white bg-emerald-600 hover:bg-emerald-700 transition-colors shadow-xs flex items-center gap-1.5 cursor-pointer disabled:opacity-50"
                >
                  {isSaving ? (
                    <>
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      <span>Salvando no banco...</span>
                    </>
                  ) : (
                    <>
                      <CheckCircle2 className="w-3.5 h-3.5" />
                      <span>Confirmar e Criar</span>
                    </>
                  )}
                </button>
              </div>
            </div>
          ) : (
            /* Formulário de Input de Mensagem em Linguagem Natural */
            <form onSubmit={handleInterpret} className="space-y-3">
              <div>
                <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-wider mb-1.5">
                  Descreva o que deseja agendar:
                </label>
                <textarea
                  rows={4}
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  placeholder='Ex: "Adicione no modelo de calendário uma tarefa de nome aaaaa com tal descrição, ela começa no dia 9, começa às 10 e termina às 12, e repete semanalmente."'
                  className={`w-full p-3 rounded-xl text-xs outline-none border transition-colors resize-none ${
                    isDarkMode
                      ? 'bg-slate-950 border-slate-800 text-slate-100 focus:border-indigo-500 placeholder:text-slate-600'
                      : 'bg-[#fcfdfd] border-[#d3dce6] text-slate-800 focus:border-indigo-600 placeholder:text-slate-400'
                  }`}
                  autoFocus
                />
              </div>

              <div className="flex items-center justify-between pt-1">
                <span className="text-[10px] text-slate-400 flex items-center gap-1">
                  <CalendarDays className="w-3.5 h-3.5 text-indigo-500" />
                  Modelo compatível inicial: <strong>Calendário</strong>
                </span>

                <button
                  type="submit"
                  disabled={!prompt.trim() || isInterpreting}
                  className="px-4 py-2 rounded-xl text-xs font-bold text-white bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 transition-all shadow-xs flex items-center gap-1.5 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isInterpreting ? (
                    <>
                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      <span>Interpretando com IA...</span>
                    </>
                  ) : (
                    <>
                      <span>Interpretar</span>
                      <ArrowRight className="w-3.5 h-3.5" />
                    </>
                  )}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}
